impl Impl { pub fn all_in_crate (db : & dyn HirDatabase , krate : Crate) -> Vec < Impl > { let mut result = Vec :: new () ; extend_with_def_map (db , crate_def_map (db , krate . id) , & mut result) ; return result ; fn extend_with_def_map (db : & dyn HirDatabase , def_map : & DefMap , result : & mut Vec < Impl > ,) { for (_ , module) in def_map . modules () { result . extend (module . scope . impls () . map (Impl :: from)) ; for unnamed_const in module . scope . unnamed_consts () { for (_ , block_def_map) in db . body (unnamed_const . into ()) . blocks (db) { extend_with_def_map (db , block_def_map , result) ; } } } } } pub fn all_in_module (db : & dyn HirDatabase , module : Module) -> Vec < Impl > { module . id . def_map (db) [module . id . local_id] . scope . impls () . map (Into :: into) . collect () } # [doc = " **Note:** This is an **approximation** that strives to give the *human-perceived notion* of an \"impl for type\","] # [doc = " **not** answer the technical question \"what are all impls applying to this type\". In particular, it excludes"] # [doc = " blanket impls, and only does a shallow type constructor check. In fact, this should've probably been on `Adt`"] # [doc = " etc., and not on `Type`. If you would want to create a precise list of all impls applying to a type,"] # [doc = " you would need to include blanket impls, and try to prove to predicates for each candidate."] pub fn all_for_type < 'db > (db : & 'db dyn HirDatabase , Type { ty , env } : Type < 'db > ,) -> Vec < Impl > { let mut result = Vec :: new () ; let interner = DbInterner :: new_with (db , Some (env . krate) , env . block) ; let Some (simplified_ty) = fast_reject :: simplify_type (interner , ty , fast_reject :: TreatParams :: AsRigid ,) else { return Vec :: new () ; } ; let mut extend_with_impls = | impls : & [ImplId] | { result . extend (impls . iter () . copied () . map (Impl :: from)) } ; extend_with_impls (method_resolution :: incoherent_inherent_impls (db , simplified_ty) ,) ; if let Some (module) = method_resolution :: simplified_type_module (db , & simplified_ty ,) { InherentImpls :: for_each_crate_and_block (db , module . krate () , module . containing_block () , & mut | impls | extend_with_impls (impls . for_self_ty (& simplified_ty)) ,) ; std :: iter :: successors (module . containing_block () , | block | { block . loc (db) . module . containing_block () } ,) . filter_map (| block | TraitImpls :: for_block (db , block) . as_deref ()) . for_each (| impls | { impls . for_self_ty (& simplified_ty , & mut extend_with_impls) }) ; for & krate in & * * db . all_crates () { TraitImpls :: for_crate (db , krate) . for_self_ty (& simplified_ty , & mut extend_with_impls) ; } } else { for & krate in & * * db . all_crates () { TraitImpls :: for_crate (db , krate) . for_self_ty (& simplified_ty , & mut extend_with_impls) ; } } result } pub fn all_for_trait (db : & dyn HirDatabase , trait_ : Trait) -> Vec < Impl > { let module = trait_ . module (db) . id ; let mut all = Vec :: new () ; let mut handle_impls = | impls : & TraitImpls | { impls . for_trait (trait_ . id , | impls | all . extend (impls . iter () . copied () . map (Impl :: from)) ,) ; } ; for krate in module . krate () . transitive_rev_deps (db) { handle_impls (TraitImpls :: for_crate (db , krate)) ; } if let Some (block) = module . containing_block () && let Some (impls) = TraitImpls :: for_block (db , block) { handle_impls (impls) ; } all } pub fn trait_ (self , db : & dyn HirDatabase) -> Option < Trait > { let trait_ref = db . impl_trait (self . id) ? ; let id = trait_ref . skip_binder () . def_id ; Some (Trait { id : id . 0 }) } pub fn trait_ref (self , db : & dyn HirDatabase) -> Option < TraitRef < '_ > > { let trait_ref = db . impl_trait (self . id) ? . instantiate_identity () ; let resolver = self . id . resolver (db) ; Some (TraitRef :: new_with_resolver (db , & resolver , trait_ref)) } pub fn self_ty (self , db : & dyn HirDatabase) -> Type < '_ > { let resolver = self . id . resolver (db) ; let ty = db . impl_self_ty (self . id) . instantiate_identity () ; Type :: new_with_resolver_inner (db , & resolver , ty) } pub fn items (self , db : & dyn HirDatabase) -> Vec < AssocItem > { self . id . impl_items (db) . items . iter () . map (| & (_ , it) | it . into ()) . collect () } pub fn is_negative (self , db : & dyn HirDatabase) -> bool { db . impl_signature (self . id) . flags . contains (ImplFlags :: NEGATIVE) } pub fn is_unsafe (self , db : & dyn HirDatabase) -> bool { db . impl_signature (self . id) . flags . contains (ImplFlags :: UNSAFE) } pub fn module (self , db : & dyn HirDatabase) -> Module { self . id . lookup (db) . container . into () } pub fn as_builtin_derive_path (self , db : & dyn HirDatabase ,) -> Option < InMacroFile < ast :: Path > > { let src = self . source (db) ? ; let macro_file = src . file_id . macro_file () ? ; let loc = macro_file . lookup (db) ; let (derive_attr , derive_index) = match loc . kind { MacroCallKind :: Derive { ast_id , derive_attr_index , derive_index , .. } => { let module_id = self . id . lookup (db) . container ; (crate_def_map (db , module_id . krate ()) [module_id . local_id] . scope . derive_macro_invoc (ast_id , derive_attr_index) ? , derive_index ,) } _ => return None , } ; let path = db . parse_macro_expansion (derive_attr) . value . 0 . syntax_node () . children () . nth (derive_index as usize) . and_then (< ast :: Attr as AstNode > :: cast) . and_then (| it | it . path ()) ? ; Some (InMacroFile { file_id : derive_attr , value : path , }) } pub fn check_orphan_rules (self , db : & dyn HirDatabase) -> bool { check_orphan_rules (db , self . id) } fn all_macro_calls (& self , db : & dyn HirDatabase ,) -> Box < [(AstId < ast :: Item > , MacroCallId)] > { self . id . impl_items (db) . macro_calls . to_vec () . into_boxed_slice () } }
